function i(t){if(t==null||isNaN(t))return"-";const r=["B","KB","MB","GB","TB","PB"];let n=0,e=t;for(;e>=1024&&n<r.length-1;)e/=1024,n++;return`${e.toFixed(n===0?0:1)} ${r[n]}`}function u(t){if(t==null||t<0)return"-";const r=Math.floor(t/86400),n=Math.floor(t%86400/3600),e=Math.floor(t%3600/60),o=Math.floor(t%60);return r>0?`${r}天${n}小时`:n>0?`${n}小时${e}分钟`:e>0?`${e}分钟${o}秒`:`${o}秒`}function f(t){return t==null?"-":t<1e3?`${t} ms`:`${(t/1e3).toFixed(1)} s`}function a(t){if(!t)return"-";const r=new Date(t);if(isNaN(r.getTime()))return"-";const n=e=>String(e).padStart(2,"0");return`${r.getFullYear()}-${n(r.getMonth()+1)}-${n(r.getDate())} ${n(r.getHours())}:${n(r.getMinutes())}:${n(r.getSeconds())}`}export{a,u as b,f as c,i as f};
